const body = $input.first().json.body;

return [{
  json: {
    message: body.message || '',
    history: body.history || [],
    clientId: body.clientId || 'default',
    businessName: body.businessName || 'AI Assistant',
    waNumber: body.waNumber || '',
    systemPrompt: body.systemPrompt || '',
    // Client-authored FAQs/knowledge-base entries from Blueflow's dashboard
    // (Client::knowledgeBaseEntries) - curated, always-current business facts
    // that don't depend on the website crawl/RAG lookup below.
    knowledgeBase: body.knowledgeBase || [],
    // The widget's per-visitor id. It's how Laravel ties an AI-only chat
    // to a human handoff conversation later, so it must be forwarded
    // untouched on every request/response round trip.
    sessionToken: body.sessionToken || ''
  }
}];

const item = $input.first().json;
const parsed = $('Parse Request').first().json;
const hasContext = Array.isArray(item.results) && item.results.length > 0;

let context = '';
let sourceUrl = '';

if (hasContext) {
  context = item.results
    .map((chunk, i) => `[Source ${i + 1} - ${chunk.url}]\n${chunk.content}`)
    .join('\n\n');

  // Use the most relevant source URL (first result)
  sourceUrl = item.results[0].url || '';
}

const historyText = (parsed.history || [])
  .slice(-6)
  .map(m => `${m.role === 'assistant' ? 'Assistant' : 'User'}: ${m.content}`)
  .join('\n');

const baseKnowledge = parsed.systemPrompt || '';

// Client-authored FAQs/knowledge-base entries - curated directly by the
// business, so the model is told to trust this over the scraped website
// context below whenever the two disagree. Present regardless of whether
// the RAG lookup above found anything, so the business's own answers never
// depend entirely on what the crawler happened to pick up.
const kbEntries = parsed.knowledgeBase || [];
const knowledgeBaseText = kbEntries.length > 0
  ? kbEntries
      .map(e => e.type === 'faq' ? `Q: ${e.title}\nA: ${e.content}` : `${e.title}\n${e.content}`)
      .join('\n\n')
  : '';
const knowledgeBaseBlock = knowledgeBaseText
  ? `--- BUSINESS KNOWLEDGE BASE (provided directly by the business - always trust this over the website content below if they ever conflict) ---\n${knowledgeBaseText}\n--- END KNOWLEDGE BASE ---\n`
  : '';

// Every prompt variant ends with the same handoff instruction so the model
// always knows how to signal "this visitor wants a human" - Extract Reply
// looks for this exact marker and turns it into a real handoff request to
// Laravel, regardless of whether we answered from website knowledge or not.
const handoffInstruction = `- If the visitor explicitly asks to speak with a human, a real person, an agent, support staff, or similar, OR seems frustrated and unable to get what they need from you, OR you genuinely don't know the answer to their question even after trying your best (both from the website knowledge and your general knowledge), respond warmly letting them know you're connecting them with the team right now, then on its own new line add exactly: HANDOFF:REQUESTED`;

// Same idea as the handoff marker: the model collects what it needs through
// plain conversation, then emits one exact line with a JSON payload once it
// truly has everything - Extract Reply parses this out and Laravel turns it
// into a real booking (or a graceful conflict/limit-reached message read
// back to the visitor).
const today = new Date().toISOString().slice(0, 10);
const appointmentInstruction = `- If the visitor wants to book an appointment, meeting, or consultation, collect their full name and an exact date and time through natural conversation, asking for anything missing one thing at a time. Today's date is ${today} - use it to resolve relative dates like "tomorrow" or "next Monday" yourself; never ask the visitor to do that math. Never invent a date/time they didn't actually give you. Once you have BOTH their name AND a specific date and time, confirm the details back to them in your reply, then on its own new line add exactly (with real values, valid JSON, 24-hour time): APPOINTMENT:BOOK {"name":"<full name>","scheduled_at":"<YYYY-MM-DD HH:MM:SS>","reason":"<brief reason if they gave one, else empty string>"}`;

// Picked up naturally during conversation, not via a checklist of questions.
// Extract Reply parses this marker and Laravel flags the matching Customer
// as a qualified lead so the client knows who's worth following up with.
const leadInstruction = `- While chatting, naturally notice what the visitor seems interested in (their intent), and if they mention it, their budget or timeline. Don't interrogate them with a checklist - just note what comes up naturally. Once you have a reasonably clear sense of their intent, on its own new line add exactly once (valid JSON): LEAD:QUALIFIED {"intent":"<what they're interested in, brief>","budget":"<their budget if mentioned, else empty string>","timeline":"<their timeline if mentioned, else empty string>"}`;

// Triggered when the visitor clicks the "Register with us" quick reply, or
// otherwise explicitly asks to leave their contact info/register/sign up.
// Distinct from the appointment/lead markers above: this needs a name PLUS
// at least one of email/phone (interest is optional, just useful context
// for whoever follows up) before it's considered complete.
const registerInstruction = `- If the visitor wants to register, sign up, or leave their details (including if they click a "Register with us" quick reply), collect their full name and at least one of email or phone through natural conversation, asking for anything missing one thing at a time. You may also ask what they're interested in, but don't insist on it. Once you have their full name AND at least one contact method, confirm the details back to them in your reply, then on its own new line add exactly (with real values, valid JSON): REGISTER:DETAILS {"name":"<full name>","email":"<email if given, else empty string>","phone":"<phone if given, else empty string>","interest":"<brief interest if mentioned, else empty string>"}`;

const systemPrompt = hasContext
  ? `You are a helpful AI assistant for ${parsed.businessName}.
${baseKnowledge}
${knowledgeBaseBlock}Use the following information from the business website to answer the visitor's question as accurately as possible:
--- WEBSITE KNOWLEDGE ---
${context}
--- END KNOWLEDGE ---
Guidelines:
- Answer naturally and conversationally
- If the context partially answers the question, use what you have and be helpful
- Never say "I don't have information" - instead offer to connect them with the team
- If unsure, say "Based on what I know, ..." and give your best answer
- Keep replies concise - 2-3 sentences max unless detail is needed
- Always end with an offer to help further
${handoffInstruction}
${appointmentInstruction}
${leadInstruction}
${registerInstruction}
- At the end of your response add exactly this on a new line: SOURCE:${sourceUrl}`
  : `You are a helpful AI assistant for ${parsed.businessName}.
${baseKnowledge}
${knowledgeBaseBlock}You don't have specific website content for this question, but use your general knowledge about this type of business to give a helpful response.
Guidelines:
- Be genuinely helpful even without specific context
- Answer general questions about the business type naturally
- For specific details like exact prices or availability, suggest they contact the team directly
- Never say "I don't have that information" bluntly - always offer an alternative
- Keep replies concise and friendly
${handoffInstruction}
${appointmentInstruction}
${leadInstruction}
${registerInstruction}`;

const userMessage = historyText
  ? `${historyText}\nUser: ${parsed.message}`
  : parsed.message;

return [{
  json: {
    systemPrompt,
    userMessage,
    businessName: parsed.businessName,
    chunksFound: hasContext ? item.results.length : 0,
    sourceUrl
  }
}];

const output = $input.first().json;
const parsed = $('Parse Request').first().json;

let reply = output.text || output.response || output.output ||
  'Sorry, I could not respond right now.';

// Extract SOURCE URL if present
let sourceUrl = '';
const sourceMatch = reply.match(/SOURCE:(https?:\/\/[^\s]+)/);
if (sourceMatch) {
  sourceUrl = sourceMatch[1];
  // Remove the SOURCE line from the reply text
  reply = reply.replace(/\nSOURCE:https?:\/\/[^\s]+/, '').trim();
}

// Detect the handoff marker the system prompt asked the model to emit
// when a visitor wants a human. Strip it out of what the visitor sees.
let wantsHandoff = false;
if (/HANDOFF:\s*REQUESTED/i.test(reply)) {
  wantsHandoff = true;
  reply = reply.replace(/\n?HANDOFF:\s*REQUESTED/i, '').trim();
}

// Detect the appointment-booking marker: APPOINTMENT:BOOK {...json...}.
// A malformed/missing JSON payload from the model is treated as "didn't
// really finish collecting details" rather than crashing the workflow.
let wantsAppointment = false;
let appointmentDetails = null;
const appointmentMatch = reply.match(/APPOINTMENT:BOOK\s*(\{[\s\S]*?\})/i);
if (appointmentMatch) {
  try {
    appointmentDetails = JSON.parse(appointmentMatch[1]);
    wantsAppointment = true;
  } catch (e) {
    wantsAppointment = false;
  }
  reply = reply.replace(/\n?APPOINTMENT:BOOK\s*\{[\s\S]*?\}/i, '').trim();
}

// Detect the lead-qualification marker: LEAD:QUALIFIED {...json...}. Like
// the appointment marker, a malformed/missing payload is treated as "the
// model didn't actually finish" rather than crashing the workflow.
let wantsLeadCapture = false;
let leadDetails = null;
const leadMatch = reply.match(/LEAD:QUALIFIED\s*(\{[\s\S]*?\})/i);
if (leadMatch) {
  try {
    leadDetails = JSON.parse(leadMatch[1]);
    wantsLeadCapture = !!(leadDetails && leadDetails.intent);
  } catch (e) {
    wantsLeadCapture = false;
  }
  reply = reply.replace(/\n?LEAD:QUALIFIED\s*\{[\s\S]*?\}/i, '').trim();
}

// Detect the registration marker: REGISTER:DETAILS {...json...}. Same
// malformed/missing-payload handling as the markers above - name plus at
// least one contact method is required, or it's treated as incomplete.
let wantsRegistration = false;
let registrationDetails = null;
const registerMatch = reply.match(/REGISTER:DETAILS\s*(\{[\s\S]*?\})/i);
if (registerMatch) {
  try {
    registrationDetails = JSON.parse(registerMatch[1]);
    wantsRegistration = !!(registrationDetails && registrationDetails.name && (registrationDetails.email || registrationDetails.phone));
  } catch (e) {
    wantsRegistration = false;
  }
  reply = reply.replace(/\n?REGISTER:DETAILS\s*\{[\s\S]*?\}/i, '').trim();
}

// The full transcript so far, for Laravel to seed the agent's inbox with
// context if this turns into a handoff.
const transcript = [
  ...(parsed.history || []),
  { role: 'user', content: parsed.message },
  { role: 'assistant', content: reply }
];

return [{
  json: {
    reply: reply.trim(),
    sourceUrl,
    wantsHandoff,
    wantsAppointment,
    appointmentDetails,
    wantsLeadCapture,
    leadDetails,
    wantsRegistration,
    registrationDetails,
    clientId: parsed.clientId,
    sessionToken: parsed.sessionToken,
    businessName: parsed.businessName,
    transcript
  }
}];

// $json here is Laravel's response from POST /api/widget/conversations:
// { status, data: { conversation_id, session_token, status, last_message_id } }
const extract = $input.first().json;
const prior = $('Extract Reply').first().json;
const data = extract.data || extract;

return [{
  json: {
    reply: prior.reply || "One moment - I'm connecting you with a member of our team now.",
    sourceUrl: prior.sourceUrl || '',
    handoff: true,
    conversationId: data.conversation_id,
    lastMessageId: data.last_message_id
  }
}];

// $json here is Laravel's response from POST /api/widget/appointments:
// success  -> { status: 'success', data: { id, scheduled_at, scheduled_at_human } }
// conflict / limit_reached / unavailable -> { status, message }
const result = $input.first().json;
const prior = $('Extract Reply').first().json;

// prior.reply already confirms the booking as if it succeeded - the model
// writes that BEFORE the actual attempt happens (see appointmentInstruction
// in Build RAG Prompt), since it doesn't know the outcome yet. That's fine
// on success, but on conflict/limit_reached/unavailable it would otherwise
// show a confirmed appointment immediately followed by "actually, that
// time is taken" - confusing, and result.message is written in the third
// person for internal use ("Ask the visitor..."), not meant to be shown
// verbatim. So anything other than success REPLACES the premature
// confirmation entirely with an honest, visitor-facing message instead of
// appending to it.
let reply;

if (result.status === 'success') {
  reply = `${prior.reply || ''}\n\nYou're all set for ${result.data.scheduled_at_human}. We look forward to seeing you!`;
} else if (result.status === 'conflict') {
  reply = "That time slot is already booked for someone else - could you give me a different date or time?";
} else if (result.status === 'limit_reached') {
  reply = "We've reached our appointment booking limit for right now, so a team member will need to book this one manually - don't worry, you won't be charged twice for it.";
} else if (result.status === 'unavailable') {
  reply = "Sorry, we can't book appointments online right now - please reach out to us directly and we'll get this sorted.";
} else {
  reply = result.message || prior.reply || '';
}

return [{
  json: {
    reply: reply.trim(),
    sourceUrl: prior.sourceUrl || '',
    appointmentStatus: result.status
  }
}];

// $json here is Laravel's response from POST /api/widget/lead: { status: 'success' } or { status: 'limit_reached' }.
// Either way this never changes what the visitor sees - lead capture is a
// silent CRM enrichment, not something that should interrupt their chat.
const prior = $('Extract Reply').first().json;

return [{
  json: {
    reply: prior.reply || '',
    sourceUrl: prior.sourceUrl || ''
  }
}];

// $json here is Laravel's response from POST /api/widget/register: { status: 'success' } or { status: 'invalid' }.
// Either way this never changes what the visitor sees - registration is a
// silent CRM save, not something that should interrupt their chat (the AI
// already confirmed the details back to them in its own reply text).
const prior = $('Extract Reply').first().json;

return [{
  json: {
    reply: prior.reply || '',
    sourceUrl: prior.sourceUrl || ''
  }
}];
